#include <vector>
#include <string>
#include <unordered_set>

class Solution {
public:
    std::vector<std::string> buildArray(std::vector<int>& target, int n) {
        std::unordered_set<int> targetSet(target.begin(), target.end());
        int maxVal = target.back();
        std::vector<std::string> ops;
        for (int x = 1; x <= maxVal; ++x) {
            ops.push_back("Push");
            if (!targetSet.count(x)) ops.push_back("Pop");
        }
        return ops;
    }
};

import java.util.*;

class Solution {
    public List<String> buildArray(int[] target, int n) {
        Set<Integer> targetSet = new HashSet<>();
        for (int x : target) targetSet.add(x);
        int maxVal = target[target.length - 1];
        List<String> ops = new ArrayList<>();
        for (int x = 1; x <= maxVal; x++) {
            ops.add("Push");
            if (!targetSet.contains(x)) ops.add("Pop");
        }
        return ops;
    }
}

var buildArray = function(target, n) {
    const targetSet = new Set(target);
    const maxVal = target[target.length - 1];
    const ops = [];
    for (let x = 1; x <= maxVal; x++) {
        ops.push("Push");
        if (!targetSet.has(x)) ops.push("Pop");
    }
    return ops;
};
